package com.xdownload.mobile;
import android.app.*;import android.content.*;import android.os.*;import android.net.Uri;import android.widget.*;import java.io.*;import java.util.*;import java.util.concurrent.*;
/** Local audio converter. Source is read-only and output is created via the Android document picker. */
public final class AudioStudioActivity extends Activity{
 static final String[] FORMATS={"mp3","m4a","aac","flac","wav","opus"};final ExecutorService io=Executors.newSingleThreadExecutor();volatile boolean dead=false;boolean busy=false,en;Uri source;File output;Spinner format,quality;EditText title,artist,start,end;TextView status;Button run,save,select;String ext="mp3";
 String tr(String a,String b){return en?b:a;}
 @Override public void onCreate(Bundle state){super.onCreate(state);en=Store.settings(this).getBoolean("english",false);ScrollView scroll=new ScrollView(this);LinearLayout l=new LinearLayout(this);l.setOrientation(1);l.setPadding(24,24,24,24);scroll.addView(l);TextView head=new TextView(this);head.setText(tr("استوديو الصوت","Audio Studio"));head.setTextSize(24);l.addView(head);select=new Button(this);select.setText(tr("اختيار ملف صوت أو فيديو","Choose audio/video file"));select.setOnClickListener(v->startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("*/*").addCategory(Intent.CATEGORY_OPENABLE),1));l.addView(select);format=new Spinner(this);format.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,FORMATS));l.addView(format);quality=new Spinner(this);quality.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"128 kbps","192 kbps","320 kbps"}));quality.setSelection(1);l.addView(quality);title=field(l,tr("عنوان اختياري","Optional title"),false);artist=field(l,tr("الفنان اختياري","Optional artist"),false);start=field(l,tr("بداية القص بالثواني (اختياري)","Trim start seconds (optional)"),true);end=field(l,tr("نهاية القص بالثواني (اختياري)","Trim end seconds (optional)"),true);run=new Button(this);run.setText(tr("تحويل","Convert"));run.setOnClickListener(v->convert());l.addView(run);save=new Button(this);save.setText(tr("حفظ النسخة الناتجة","Save output"));save.setOnClickListener(v->startActivityForResult(new Intent(Intent.ACTION_CREATE_DOCUMENT).setType(MediaEngine.mime(ext,true)).addCategory(Intent.CATEGORY_OPENABLE).putExtra(Intent.EXTRA_TITLE,"XDownload-audio."+ext),2));l.addView(save);status=new TextView(this);status.setText(tr("التحويل محلي. معدل البت لا ينطبق على FLAC وWAV ولا يرفع جودة المصدر.","Local conversion. Bitrate does not apply to FLAC/WAV or improve source quality."));l.addView(status);setContentView(scroll);state(false);}
 EditText field(LinearLayout l,String hint,boolean number){EditText e=new EditText(this);e.setHint(hint);e.setSingleLine(true);if(number)e.setInputType(8194);l.addView(e);return e;}
 void state(boolean b){busy=b;select.setEnabled(!b);run.setEnabled(!b&&source!=null);save.setEnabled(!b&&output!=null);format.setEnabled(!b);quality.setEnabled(!b);}
 @Override protected void onActivityResult(int req,int result,Intent data){super.onActivityResult(req,result,data);if(result!=RESULT_OK||data==null||data.getData()==null)return;Uri uri=data.getData();if(req==1){source=uri;status.setText(tr("تم اختيار الملف","Source selected"));state(false);}else if(req==2&&output!=null){File f=output;state(true);io.execute(()->{try(InputStream in=new FileInputStream(f);OutputStream out=getContentResolver().openOutputStream(uri,"w")){if(out==null)throw new IOException("Unable to open output");copy(in,out);report(tr("تم الحفظ","Saved"));}catch(Exception e){report("Save failed: "+e.getMessage());}});}}
 static void copy(InputStream in,OutputStream out)throws IOException{if(in==null)throw new IOException("Cannot read source");byte[] b=new byte[65536];int n;while((n=in.read(b))!=-1){if(Thread.currentThread().isInterrupted())throw new IOException("Cancelled");out.write(b,0,n);}}
 void convert(){if(busy||source==null)return;String fmt=FORMATS[format.getSelectedItemPosition()];int rate=new int[]{128,192,320}[quality.getSelectedItemPosition()];String name=title.getText().toString(),author=artist.getText().toString();double a=0,b=-1;try{if(!start.getText().toString().isEmpty())a=Double.parseDouble(start.getText().toString());if(!end.getText().toString().isEmpty())b=Double.parseDouble(end.getText().toString());if(!Double.isFinite(a)||!Double.isFinite(b)||a<0||b!=-1&&b<=a)throw new IllegalArgumentException();}catch(Exception e){status.setText(tr("أوقات القص غير صحيحة","Invalid trim times"));return;}final double from=a,to=b;Uri selected=source;state(true);status.setText(tr("جارٍ التحويل…","Converting…"));io.execute(()->{File input=null,result=null;try{input=File.createTempFile("studio-in-",".tmp",getCacheDir());result=File.createTempFile("studio-out-","."+fmt,getCacheDir());try(InputStream in=getContentResolver().openInputStream(selected);OutputStream out=new FileOutputStream(input)){copy(in,out);}encode(this,input,result,fmt,rate,name,author,from,to);if(dead){result.delete();return;}final File done=result;result=null;runOnUiThread(()->{if(dead){done.delete();return;}if(output!=null)output.delete();output=done;ext=fmt;status.setText(tr("جاهز للحفظ: ","Ready to save: ")+MainActivity.size(done.length()));state(false);});}catch(Exception|LinkageError e){report("Conversion failed: "+e.getMessage());}finally{if(input!=null)input.delete();if(result!=null)result.delete();}});}
 static void encode(Context context,File in,File out,String fmt,int rate,String title,String artist,double start,double end)throws IOException{
  String codec;switch(fmt){case "mp3":codec="libmp3lame";break;case "m4a":case "aac":codec="aac";break;case "flac":codec="flac";break;case "wav":codec="pcm_s16le";break;case "opus":codec="libopus";break;default:throw new IOException("Invalid output format");}
  if(rate!=128&&rate!=192&&rate!=320||!Double.isFinite(start)||!Double.isFinite(end)||start<0||end!=-1&&end<=start)throw new IOException("Invalid audio settings");ArrayList<String> args=new ArrayList<>(Arrays.asList("-y","-i",in.getAbsolutePath(),"-vn","-map","0:a:0","-c:a",codec));if(start>0)args.addAll(Arrays.asList("-ss",Double.toString(start)));if(end>=0)args.addAll(Arrays.asList("-t",Double.toString(end-start)));if(!fmt.equals("flac")&&!fmt.equals("wav"))args.addAll(Arrays.asList("-b:a",rate+"k"));if(!title.isEmpty())args.addAll(Arrays.asList("-metadata","title="+title.substring(0,Math.min(title.length(),200))));if(!artist.isEmpty())args.addAll(Arrays.asList("-metadata","artist="+artist.substring(0,Math.min(artist.length(),200))));args.add(out.getAbsolutePath());NativeMedia.run(context,args.toArray(new String[0]));if(out.length()<44)throw new IOException("Encoder did not produce valid output");}
 void report(String text){runOnUiThread(()->{if(!dead){status.setText(text);state(false);}});}
 @Override protected void onDestroy(){dead=true;io.shutdownNow();if(output!=null)output.delete();super.onDestroy();}
}